package com.simibubi.create.test;

import com.mojang.blaze3d.platform.InputConstants;
import com.simibubi.create.*;
import com.simibubi.create.content.kinetics.base.*;
import com.simibubi.create.content.kinetics.motor.*;
import com.simibubi.create.content.kinetics.speedController.*;
import java.util.concurrent.atomic.*;
import net.fabricmc.fabric.api.client.gametest.v1.context.*;
import net.minecraft.core.*;
import net.minecraft.world.phys.Vec3;

final class SpeedControllerRenderingTest {
    private static final BlockPos P=new BlockPos(680,4,5),MOTOR=P.west(),REVERSE=new BlockPos(690,4,5);
    static void run(ClientGameTestContext context,TestSingleplayerContext world){
        var server=world.getServer();var oldHud=new AtomicBoolean();context.runOnClient(client->{oldHud.set(client.gui.hud.isHidden());if(oldHud.get())client.gui.hud.toggle();});server.runCommand("gamemode spectator @p");server.runCommand("tp @p 686 8 12");context.waitFor(client->Math.abs(client.player.getX()-686.5)<0.1&&client.level.isLoaded(new BlockPos(705,5,5)),500);server.runCommand("fill 674 3 1 710 3 12 minecraft:smooth_quartz");
        server.runCommand("setblock 679 4 5 create:creative_motor[facing=east]");server.runCommand("setblock 680 4 5 create:rotation_speed_controller[axis=x]");server.runCommand("setblock 681 4 5 create:shaft[axis=x]");
        server.runCommand("setblock 690 4 5 create:rotation_speed_controller[axis=x]");server.runCommand("setblock 690 5 5 create:large_cogwheel[axis=z]");server.runCommand("setblock 690 5 4 create:creative_motor[facing=south]");server.runCommand("setblock 691 4 5 create:speedometer[facing=up,axis_along_first=true]");
        server.runCommand("gamemode creative @p");server.runCommand("tp @p 680 4 9");server.runCommand("item replace entity @p weapon.mainhand with minecraft:air");context.waitFor(client->Math.abs(client.player.getX()-680.5)<0.1&&!client.player.isSpectator()&&client.player.getMainHandItem().isEmpty(),200);
        checkBracket(context,P,false);look(context,P);context.getInput().pressKey(options->options.keyUse);context.waitTicks(7);context.runOnClient(client->{if(client.gui.screen()!=null||((SpeedControllerBlockEntity)client.level.getBlockEntity(P)).getTargetSpeed()!=16)throw new AssertionError("Short interaction changed setting or opened value board");var state=(KineticRenderState)client.getBlockEntityRenderDispatcher().tryExtractRenderState(client.level.getBlockEntity(P),0.5f,null,false);if(state.speedSetting==null||!state.speedSetting.highlighted())throw new AssertionError("Controller value box not extracted");});world.getConnection().waitForChunksRender();screenshot(context,"create-vulkan-speed-controller-value-box");
        open(context,P);choose(context,0,73);context.waitFor(client->((SpeedControllerBlockEntity)client.level.getBlockEntity(P)).getTargetSpeed()==-73,200);assertServerSetting(context,world,P,-73);
        server.runCommand("setblock 680 5 5 create:large_cogwheel[axis=z]");context.waitFor(client->client.level.getBlockEntity(P.above()) instanceof KineticBlockEntity cog&&cog.getSpeed()==-73,200);checkBracket(context,P,true);
        context.getInput().lookAt(new BlockPos(680,5,5));world.getConnection().waitForChunksRender();screenshot(context,"create-vulkan-speed-controller-shaft-driven");
        look(context,P);open(context,P);moveToValue(context,1,64);context.getInput().scroll(1);context.getInput().releaseKey(options->options.keyUse);context.waitFor(client->client.gui.screen()==null&&((SpeedControllerBlockEntity)client.level.getBlockEntity(P)).getTargetSpeed()==65,200);assertServerSetting(context,world,P,65);
        open(context,P);moveToValue(context,1,64);context.getInput().holdKey(InputConstants.KEY_LSHIFT);context.getInput().scroll(1);context.getInput().releaseKey(options->options.keyUse);context.waitFor(client->client.gui.screen()==null&&((SpeedControllerBlockEntity)client.level.getBlockEntity(P)).getTargetSpeed()==96,200);context.getInput().releaseKey(InputConstants.KEY_LSHIFT);assertServerSetting(context,world,P,96);
        // The same held-use board replaces the motor's temporary power-of-two click cycle.
        server.runCommand("tp @p 679 4 9");context.waitFor(client->Math.abs(client.player.getX()-679.5)<0.1,200);open(context,MOTOR);choose(context,0,91);context.waitFor(client->((KineticBlockEntity)client.level.getBlockEntity(MOTOR)).getGeneratedSpeedSetting()==-91,200);assertServerSetting(context,world,MOTOR,-91);
        context.runOnClient(client->{if(((KineticBlockEntity)client.level.getBlockEntity(P.above())).getSpeed()!=96)throw new AssertionError("Motor setting changed regulated output target");});
        open(context,MOTOR);context.getInput().pressKey(InputConstants.KEY_ESCAPE);context.getInput().releaseKey(options->options.keyUse);context.waitFor(client->client.gui.screen()==null,200);assertServerSetting(context,world,MOTOR,-91);
        // Cog-powered mode and the second horizontal controller orientation.
        server.runOnServer(ignored->((SpeedControllerBlockEntity)world.getConnection().getServerLevel().getBlockEntity(REVERSE)).setTargetSpeed(-112));context.waitFor(client->client.level.getBlockEntity(REVERSE) instanceof KineticBlockEntity shaft&&shaft.getSpeed()==-112,200);checkBracket(context,REVERSE,true);
        server.runCommand("setblock 701 4 5 create:rotation_speed_controller[axis=z]");server.runCommand("setblock 701 5 5 create:large_cogwheel[axis=x]");server.runCommand("setblock 701 5 4 create:creative_motor[facing=south]");server.runCommand("tp @p 695 7 11");context.waitFor(client->Math.abs(client.player.getX()-695.5)<0.1&&client.level.getBlockEntity(new BlockPos(701,4,5)) instanceof SpeedControllerBlockEntity,200);checkBracket(context,new BlockPos(701,4,5),true);
        context.getInput().lookAt(new BlockPos(690,5,5));world.getConnection().waitForChunksRender();screenshot(context,"create-vulkan-speed-controller-cog-driven");
        var oldMesh=new AtomicReference<Object>();context.runOnClient(client->oldMesh.set(((KineticRenderState)client.getBlockEntityRenderDispatcher().tryExtractRenderState(client.level.getBlockEntity(P),0.5f,null,false)).controllerBracket.mesh));var reload=context.computeOnClient(client->client.reloadResourcePacks());context.waitFor(client->reload.isDone()&&client.gui.overlay()==null,600);context.waitTicks(5);checkBracket(context,P,true);context.runOnClient(client->{if(((KineticRenderState)client.getBlockEntityRenderDispatcher().tryExtractRenderState(client.level.getBlockEntity(P),0.5f,null,false)).controllerBracket.mesh==oldMesh.get())throw new AssertionError("Controller bracket retained stale mesh after reload");});
        server.runCommand("setblock 680 5 5 minecraft:air");context.waitFor(client->client.level.getBlockState(P.above()).isAir(),200);checkBracket(context,P,false);server.runCommand("gamemode spectator @p");chunkUnload(context,world);context.runOnClient(client->{if(client.gui.hud.isHidden()!=oldHud.get())client.gui.hud.toggle();});
    }
    private static void look(ClientGameTestContext context,BlockPos pos){
        context.getInput().lookAt(pos);context.waitFor(client->client.hitResult instanceof net.minecraft.world.phys.BlockHitResult hit&&hit.getBlockPos().equals(pos)&&KineticSpeedSettings.testHit(client.level.getBlockState(pos),hit),200);
    }
    private static void open(ClientGameTestContext context,BlockPos pos){look(context,pos);context.getInput().holdKey(options->options.keyUse);context.waitFor(client->client.gui.screen() instanceof KineticSpeedScreen screen&&screen.position().equals(pos),200);}
    private static void choose(ClientGameTestContext context,int row,int speed){moveToValue(context,row,speed);context.waitTicks(3);context.takeScreenshot("create-vulkan-kinetic-speed-value-board");context.getInput().releaseKey(options->options.keyUse);context.waitFor(client->client.gui.screen()==null,200);}
    private static void moveToValue(ClientGameTestContext context,int row,int speed){
        var at=coordinate(context,row,speed);
        // Native mouse grab discards its first move; follow it with a real move onto the board.
        context.getInput().setCursorPos(0,0);context.waitTicks(1);context.getInput().setCursorPos(at.x,at.y);
        context.waitFor(client->client.gui.screen() instanceof KineticSpeedScreen screen&&screen.children().stream().filter(com.simibubi.create.foundation.gui.widget.ScheduleEditBox.class::isInstance).map(com.simibubi.create.foundation.gui.widget.ScheduleEditBox.class::cast).anyMatch(input->input.getValue().equals(Integer.toString(speed))),200);
    }
    private static net.minecraft.world.phys.Vec2 coordinate(ClientGameTestContext context,int row,int speed){return context.computeOnClient(client->{var at=((KineticSpeedScreen)client.gui.screen()).getCoordinateOfValue(row,speed);var window=client.getWindow();return new net.minecraft.world.phys.Vec2(at.x*window.getScreenWidth()/window.getGuiScaledWidth(),at.y*window.getScreenHeight()/window.getGuiScaledHeight());});}
    private static void assertServerSetting(ClientGameTestContext context,TestSingleplayerContext world,BlockPos pos,int expected){var match=new AtomicBoolean();for(int i=0;i<100&&!match.get();i++){context.waitTicks(1);world.getServer().runOnServer(ignored->{var entity=(KineticBlockEntity)world.getConnection().getServerLevel().getBlockEntity(pos);match.set(KineticSpeedSettings.value(entity)==expected);});}if(!match.get())throw new AssertionError("Server did not receive value settings packet "+expected);}
    private static void checkBracket(ClientGameTestContext context,BlockPos pos,boolean present){context.runOnClient(client->{var entity=client.level.getBlockEntity(pos);var state=(KineticRenderState)client.getBlockEntityRenderDispatcher().tryExtractRenderState(entity,0.5f,null,false);if(state==null||state.model.isEmpty()||state.controllerBracket.isEmpty()==present||present&&(state.controllerBracket.mesh==null||state.controllerBracket.mesh.size()==0))throw new AssertionError("Controller shaft/bracket extraction failed at "+pos);});}
    private static void screenshot(ClientGameTestContext context,String name){context.runOnClient(client->client.gui.hud.getChat().clearMessages(false));context.waitTicks(2);context.takeScreenshot(name);}
    private static void chunkUnload(ClientGameTestContext context,TestSingleplayerContext world){
        var server=world.getServer();var controller=new BlockPos(751,4,5);var source=new BlockPos(768,4,5);server.runCommand("tp @p 760 8 12");context.waitFor(client->Math.abs(client.player.getX()-760.5)<0.1&&client.level.isLoaded(source),500);
        server.runCommand("fill 747 3 1 772 3 14 minecraft:smooth_quartz");server.runCommand("setblock 751 4 5 create:rotation_speed_controller[axis=x]");server.runCommand("setblock 751 5 5 create:large_cogwheel[axis=z]");server.runCommand("fill 752 4 5 767 4 5 create:shaft[axis=x]");server.runCommand("setblock 768 4 5 create:creative_motor[facing=west]");
        server.runOnServer(ignored->{var level=world.getConnection().getServerLevel();((SpeedControllerBlockEntity)level.getBlockEntity(controller)).setTargetSpeed(96);level.getChunkSource().addTicket(new net.minecraft.server.level.Ticket(net.minecraft.server.level.TicketType.FORCED,32),new net.minecraft.world.level.ChunkPos(46,0));});context.waitFor(client->client.level.getBlockEntity(controller.above()) instanceof KineticBlockEntity cog&&cog.getSpeed()==96,200);
        var retainedCapacity=new AtomicReference<Double>();var retainedNetwork=new AtomicReference<Long>();
        server.runOnServer(ignored->{var level=world.getConnection().getServerLevel();var cog=(KineticBlockEntity)com.simibubi.create.foundation.utility.LoadedLevelAccess.blockEntity(level,controller.above());if(cog==null||cog.getSpeed()!=96||cog.getStressCapacity()<=0||!level.isLoaded(source))throw new AssertionError("Native powered controller must be ready before unload");retainedCapacity.set(cog.getStressCapacity());retainedNetwork.set(cog.network);});
        server.runCommand("tp @p 5000 10 5000");var unloaded=new AtomicBoolean();for(int attempt=0;attempt<120&&!unloaded.get();attempt++){context.waitTicks(5);server.runOnServer(ignored->unloaded.set(!world.getConnection().getServerLevel().isLoaded(source)));}if(!unloaded.get())throw new AssertionError("Controller kept source chunk loaded");context.waitTicks(20);
        // Pinned Create retains RPM and unloaded network capacity while its upstream chunk is absent.
        server.runOnServer(ignored->{var level=world.getConnection().getServerLevel();var cog=(KineticBlockEntity)com.simibubi.create.foundation.utility.LoadedLevelAccess.blockEntity(level,controller.above());var boundary=(KineticBlockEntity)com.simibubi.create.foundation.utility.LoadedLevelAccess.blockEntity(level,source.west());var regulator=(SpeedControllerBlockEntity)com.simibubi.create.foundation.utility.LoadedLevelAccess.blockEntity(level,controller);if(!level.isLoaded(controller)||cog==null||cog.getSpeed()!=96||cog.getTheoreticalSpeed()!=96||cog.getStressCapacity()!=retainedCapacity.get()||!java.util.Objects.equals(cog.network,retainedNetwork.get())||!source.equals(cog.getGeneratingSource())||boundary==null||!source.equals(boundary.getSource())||boundary.getSpeed()!=-16||boundary.getStressCapacity()!=retainedCapacity.get()||regulator==null||regulator.getTargetSpeed()!=96||level.isLoaded(source)||com.simibubi.create.foundation.utility.LoadedLevelAccess.isLoaded(level,source))throw new AssertionError("Unloaded native boundary changed the original RPM, network capacity, provenance or target");});
        server.runCommand("tp @p 760 8 12");context.waitFor(client->Math.abs(client.player.getX()-760.5)<0.1&&client.level.getBlockEntity(controller.above()) instanceof KineticBlockEntity cog&&cog.getSpeed()==96,500);
        context.waitFor(client->client.level.getBlockEntity(source) instanceof KineticBlockEntity,200);
        var returned=new AtomicBoolean();for(int attempt=0;attempt<200&&!returned.get();attempt++){context.waitTicks(1);server.runOnServer(ignored->{var level=world.getConnection().getServerLevel();returned.set(Math.abs(level.players().getFirst().getX()-760.5)<0.1&&level.isLoaded(source)&&com.simibubi.create.foundation.utility.LoadedLevelAccess.blockEntity(level,source) instanceof KineticBlockEntity);});}if(!returned.get())throw new AssertionError("Native source column did not finish returning before actual motor stop");
        // A genuinely loaded, stopped source must remove all output RPM and capacity.
        server.runOnServer(ignored->{var level=world.getConnection().getServerLevel();var motor=(KineticBlockEntity)com.simibubi.create.foundation.utility.LoadedLevelAccess.blockEntity(level,source);if(!level.isLoaded(source)||motor==null)throw new AssertionError("Actual source chunk did not return");motor.setGeneratedSpeed(0);});
        context.waitFor(client->client.level.getBlockEntity(controller.above()) instanceof KineticBlockEntity cog&&cog.getSpeed()==0&&cog.getStressCapacity()==0,200);
        server.runOnServer(ignored->{var level=world.getConnection().getServerLevel();var cog=(KineticBlockEntity)com.simibubi.create.foundation.utility.LoadedLevelAccess.blockEntity(level,controller.above());var motor=(KineticBlockEntity)com.simibubi.create.foundation.utility.LoadedLevelAccess.blockEntity(level,source);if(!level.isLoaded(controller)||!level.isLoaded(source)||cog==null||cog.getSpeed()!=0||cog.getStressCapacity()!=0||motor==null||motor.getGeneratedSpeedSetting()!=0)throw new AssertionError("Loaded regulator continued generating power after actual source stopped");motor.setGeneratedSpeed(16);});
        context.waitFor(client->client.level.getBlockEntity(controller.above()) instanceof KineticBlockEntity cog&&cog.getSpeed()==96&&cog.getStressCapacity()==retainedCapacity.get(),200);
        server.runOnServer(ignored->{var level=world.getConnection().getServerLevel();var cog=(KineticBlockEntity)com.simibubi.create.foundation.utility.LoadedLevelAccess.blockEntity(level,controller.above());if(cog==null||cog.getSpeed()!=96||cog.getStressCapacity()!=retainedCapacity.get()||!source.equals(cog.getGeneratingSource())||((SpeedControllerBlockEntity)com.simibubi.create.foundation.utility.LoadedLevelAccess.blockEntity(level,controller)).getTargetSpeed()!=96)throw new AssertionError("Native source restart did not recover the unchanged regulated target and capacity");});
        server.runOnServer(ignored->world.getConnection().getServerLevel().getChunkSource().removeTicketWithRadius(net.minecraft.server.level.TicketType.FORCED,new net.minecraft.world.level.ChunkPos(46,0),1));context.getInput().lookAt(controller);world.getConnection().waitForChunksRender();screenshot(context,"create-vulkan-speed-controller-chunk-returned");
    }
}
